from pathlib import Path

tex_path = Path("main.tex")
content = tex_path.read_text(encoding="utf-8")

target = r"""    \item \textbf{Efectividad de la estrategia integral (Escenario 2):} Al articular la eliminación del pánico con la expansión del 27,3\% en el régimen de turnos de envasado ($\text{escalaTurno} = 3{,}3$, elevando la jornada semanal a 51 horas efectivas), el sistema supera la restricción de flujo y entra en verdadero estado estacionario. El nivel de servicio global se eleva al 92,42\% ($\pm 2,03\%$, IC 95\%: $[90,39\% ; 94,46\%]$), mientras que el backlog medio se contrae drásticamente a 520.291 cajas. La comparación pareada ($\Delta = \text{Escenario 2} - \text{Escenario 0}$) arroja una mejora neta media en el Fill Rate de $+10,89$ puntos porcentuales (con un error estándar de apenas $0,21\%$ gracias al pareamiento CRN, e IC 95\%: $[+10,47\% ; +11,30\%]$) y una reducción del backlog de 690.503 cajas (IC 95\%: $[-718.112 ; -662.894]$ cajas, caída del 57,0\%). Asimismo, el stock operativo en depósito se estabiliza en 40.999 cajas, amortiguando eficazmente la variabilidad de la demanda. Ninguno de los intervalos de confianza pareados contiene al cero, lo que ratifica con una significancia estadística superior al 99,9\% ($p < 0{,}001$) la superioridad indiscutible de la política combinada.
\end{enumerate}"""

replacement = r"""    \item \textbf{Efectividad de la estrategia integral (Escenario 2):} Al articular la eliminación del pánico con la expansión del 27,3\% en el régimen de turnos de envasado ($\text{escalaTurno} = 3{,}3$, elevando la jornada semanal a 51 horas efectivas), el sistema supera la restricción de flujo y entra en verdadero estado estacionario. El nivel de servicio global se eleva al 92,42\% ($\pm 2,03\%$, IC 95\%: $[90,39\% ; 94,46\%]$), mientras que el backlog medio se contrae drásticamente a 520.291 cajas. La comparación pareada ($\Delta = \text{Escenario 2} - \text{Escenario 0}$) arroja una mejora neta media en el Fill Rate de $+10,89$ puntos porcentuales (con un error estándar de apenas $0,21\%$ gracias al pareamiento CRN, e IC 95\%: $[+10,47\% ; +11,30\%]$) y una reducción del backlog de 690.503 cajas (IC 95\%: $[-718.112 ; -662.894]$ cajas, caída del 57,0\%). Asimismo, el stock operativo en depósito se estabiliza en 40.999 cajas, amortiguando eficazmente la variabilidad de la demanda. Ninguno de los intervalos de confianza pareados contiene al cero, lo que ratifica con una significancia estadística superior al 99,9\% ($p < 0{,}001$) la superioridad indiscutible de la política combinada.
    \item \textbf{Vulnerabilidad diferencial por canal comercial:} El contraste entre segmentos confirma el segundo interrogante del estudio: la demanda atomizada de la Red Propia (428 distribuidores con pedidos regulares) presenta una variabilidad moderada que la planta absorbe con un nivel de servicio elevado. Por el contrario, la alta concentración y dispersión de las grandes cadenas (Maxiconsumo S.A. y supermercados, donde el desvío supera a la media: $\sigma > \mu$ en lavandina y desinfectante) actúan como el principal inductor de quiebres de stock y colas de backlog en la situación base. La estrategia integral del Escenario 2 mitiga esta asimetría, garantizando el cumplimiento de los contratos mayoristas sin desproteger a la red de distribución capilar.
\end{enumerate}"""

assert target in content, "Target not found in main.tex"
content = content.replace(target, replacement, 1)
tex_path.write_text(content, encoding="utf-8")
print("Item 4 agregado exitosamente!")
